//! Parity and regression tests for the MOSS-TTS family.
//!
//! Pinned fixtures reside in `testdata/tts_moss_tts/`, generated by
//! `tools/gen_moss_tts_fixtures.py` against mlx-audio 0.5.7 commit
//! `e1b19b9054bf163f5d812221a54fcc346f1890e9` (mlx 0.32.3). The
//! generator runs the true reference modules (a deterministic
//! character-level tokenizer with multi-char special tokens stands in
//! for the checkpoint tokenizer, a seeded tiny mono MOSS audio tokenizer
//! for the codec, greedy sampling throughout, and engineered text-head
//! rows so the delay bookkeeping and the continue/stop choices are
//! deterministic), so the traces carry the unified-code grids from
//! `MossTTSDelayProcessor`, the v1.5 row layouts from
//! `MossTTSLocalV15Processor`, the `generate_delay_pattern_ids` and
//! `generate_v15_local_ids` tails, the `_decode_generated_audio`
//! trim/decode, the family sampler chain, and the delay pattern round
//! trip.

use std::path::{Path, PathBuf};

use serde_json::Value;

use super::sampling as family_sampling;
use super::{
    apply_de_delay_pattern, apply_delay_pattern, normalize_audio_codes, DelayMessage, DelayMode,
    DelayParams, GenerationParams, Model, ModelConfig, Role, V15Params, V15PromptMode,
    V15TemplateIds, Variant,
};
use crate::codec::moss_audio_tokenizer::MossAudioTokenizer;

fn testdata(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("testdata/tts_moss_tts")
        .join(name)
}

fn read_json(path: &Path) -> Value {
    let text = std::fs::read_to_string(path).expect("fixture json");
    serde_json::from_str(&text).expect("fixture json")
}

fn i32_vec(value: &Value) -> Vec<i32> {
    value
        .as_array()
        .expect("ids")
        .iter()
        .map(|v| v.as_i64().expect("id") as i32)
        .collect()
}

fn i32_rows(value: &Value) -> Vec<Vec<i32>> {
    value
        .as_array()
        .expect("rows")
        .iter()
        .map(i32_vec)
        .collect()
}

fn f32_vec(value: &Value) -> Vec<f32> {
    value
        .as_array()
        .expect("values")
        .iter()
        .map(|v| v.as_f64().expect("value") as f32)
        .collect()
}

/// Filtered sampler scores use null for the reference's negative
/// infinities (strict JSON cannot carry them).
fn f32_vec_masked(value: &Value) -> Vec<f32> {
    value
        .as_array()
        .expect("values")
        .iter()
        .map(|v| {
            if v.is_null() {
                f32::NEG_INFINITY
            } else {
                v.as_f64().expect("value") as f32
            }
        })
        .collect()
}

fn max_abs_diff(a: &[f32], b: &[f32]) -> f32 {
    assert_eq!(
        a.len(),
        b.len(),
        "length mismatch: {} vs {}",
        a.len(),
        b.len()
    );
    a.iter()
        .zip(b)
        .map(|(x, y)| (x - y).abs())
        .fold(0.0f32, f32::max)
}

/// Measured maximum difference against the fixture waveforms when the
/// gate was frozen; the assertion uses this value, not a re-measured
/// one. The MOSS codec decode parity measured 6.9e-7 for the nano family
/// (conv accumulation order), so the gate sits well above it.
const WAVEFORM_TOLERANCE: f32 = 2e-6;

fn delay_model(case: &str) -> Model {
    Model::open(&testdata(case)).expect("delay model loads")
}

fn audio_tokenizer() -> MossAudioTokenizer {
    MossAudioTokenizer::open(&testdata("decode")).expect("tiny moss codec loads")
}

fn delay_config() -> ModelConfig {
    let value = read_json(&testdata("delay_generate/config.json"));
    ModelConfig::from_json(&value).expect("delay config parses")
}

fn v15_config() -> ModelConfig {
    let value = read_json(&testdata("v15_generate/config.json"));
    ModelConfig::from_json(&value).expect("v15 config parses")
}

fn reference_codes() -> Vec<Vec<i32>> {
    let traces = read_json(&testdata("decode/traces.json"));
    i32_rows(&traces["encode_codes"])
}

#[test]
fn config_selects_the_reference_variants() {
    let delay = delay_config();
    assert_eq!(delay.variant(), Variant::Delay);
    assert_eq!(delay.model_type, "moss_tts_delay");
    assert_eq!(delay.n_vq, 4);
    assert_eq!(delay.audio_pad_code, 16);
    assert_eq!(
        delay.audio_tokenizer_repo,
        super::DEFAULT_AUDIO_TOKENIZER_REPO
    );

    let v15 = v15_config();
    assert_eq!(v15.variant(), Variant::V15Local);
    assert_eq!(v15.model_type, "moss_tts_local");
    assert_eq!(v15.local_gpt2_config().unwrap().n_layer, 1);
    assert_eq!(v15.local_gpt2_config().unwrap().n_positions, 5);

    // A v1.5 selection through gpt2_config alone (model_type delay).
    let mut value = read_json(&testdata("delay_generate/config.json"));
    value["gpt2_config"] = read_json(&testdata("v15_generate/config.json"))["gpt2_config"].clone();
    let config = ModelConfig::from_json(&value).unwrap();
    assert_eq!(config.variant(), Variant::V15Local);

    // The legacy local fields select the refused legacy variant.
    let mut value = read_json(&testdata("delay_generate/config.json"));
    value["additional_mlp_ffn_hidden_size"] = serde_json::json!(64);
    value["local_ffn_hidden_size"] = serde_json::json!(64);
    value["local_hidden_size"] = serde_json::json!(32);
    value["local_num_layers"] = serde_json::json!(2);
    let config = ModelConfig::from_json(&value).unwrap();
    assert_eq!(config.variant(), Variant::LegacyLocal);
    let legacy = serde_json::json!({
        "model_type": "moss_tts_delay",
        "n_vq": 4,
        "language_config": {
            "model_type": "qwen3",
            "hidden_size": 32,
            "num_hidden_layers": 1,
            "intermediate_size": 64,
            "num_attention_heads": 4,
            "num_key_value_heads": 2,
            "head_dim": 8,
            "rms_norm_eps": 1e-5,
            "vocab_size": 96,
            "max_position_embeddings": 512,
            "rope_theta": 10000.0,
            "tie_word_embeddings": false,
        },
        "additional_mlp_ffn_hidden_size": 64,
        "local_ffn_hidden_size": 64,
        "local_hidden_size": 32,
        "local_num_layers": 2,
    });
    let parsed = ModelConfig::from_json(&legacy).unwrap();
    assert_eq!(parsed.variant(), Variant::LegacyLocal);
    let error = Model::load(
        &crate::lm::Weights::open_single(&testdata("decode/model.safetensors")).unwrap(),
        &legacy,
    )
    .err()
    .expect("legacy local loads are refused");
    assert!(error.to_string().contains("not ported"));

    // The config defaults the reference from_dict keeps.
    let config = ModelConfig::from_json(&serde_json::json!({
        "language_config": {
            "model_type": "qwen3",
            "hidden_size": 32,
            "num_hidden_layers": 1,
            "intermediate_size": 64,
            "num_attention_heads": 4,
            "num_key_value_heads": 2,
            "head_dim": 8,
            "rms_norm_eps": 1e-5,
            "vocab_size": 96,
            "max_position_embeddings": 512,
            "rope_theta": 10000.0,
            "tie_word_embeddings": false,
        },
    }))
    .unwrap();
    assert_eq!(config.model_type, "moss_tts_delay");
    assert_eq!(config.n_vq, 32);
    assert_eq!(config.audio_vocab_size, 1024);
    assert_eq!(config.audio_pad_token_id, 1024);
    assert_eq!(config.audio_pad_code, 1024);
    assert_eq!(config.audio_user_slot_token_id, 151654);
    assert_eq!(config.audio_assistant_slot_token_id, 151656);
    assert_eq!(config.audio_assistant_gen_slot_token_id, 151656);
    assert_eq!(config.audio_assistant_delay_slot_token_id, 151662);
    assert_eq!(config.audio_start_token_id, 151652);
    assert_eq!(config.audio_end_token_id, 151653);
    assert_eq!(config.pad_token_id, 151643);
    assert_eq!(config.im_start_token_id, 151644);
    assert_eq!(config.im_end_token_id, 151645);
    assert_eq!(config.sampling_rate, 24000);
    assert_eq!(config.local_transformer_layers, 1);
    assert_eq!(config.local_text_head_mode, "full_vocab");
    assert!(config.use_static_local_kv_cache);
    assert_eq!(config.codebook_sizes(), vec![1024; 32]);
}

/// Rebuilds the recorded content pieces into the Rust piece list.
fn recorded_pieces(value: &Value) -> Vec<super::ContentPiece<'static>> {
    let mut pieces = Vec::new();
    for piece in value.as_array().expect("pieces") {
        match piece["kind"].as_str().expect("kind") {
            "text" => pieces.push(super::ContentPiece::Text(i32_vec(&piece["ids"]).leak())),
            "audio" => pieces.push(super::ContentPiece::Audio(i32_rows(&piece["codes"]).leak())),
            other => panic!("unknown piece kind {other}"),
        }
    }
    pieces
}

#[test]
fn delay_prompt_rows_match_the_reference_grids() {
    let traces = read_json(&testdata("delay_prompt/traces.json"));
    let model = delay_model("delay_generate");
    let template = super::ChatTemplateIds {
        user_role: i32_vec(&traces["template"]["user_role"]).leak(),
        assistant_role: i32_vec(&traces["template"]["assistant_role"]).leak(),
        after_im_end: i32_vec(&traces["template"]["after_im_end"]).leak(),
    };
    for case in traces["cases"].as_array().expect("cases") {
        let mode = match case["mode"].as_str().expect("mode") {
            "generation" => DelayMode::Generation,
            "continuation" => DelayMode::Continuation,
            other => panic!("unknown mode {other}"),
        };
        let messages: Vec<DelayMessage> = case["messages"]
            .as_array()
            .expect("messages")
            .iter()
            .map(|message| DelayMessage {
                role: match message["role"].as_str().expect("role") {
                    "user" => Role::User,
                    "assistant" => Role::Assistant,
                    other => panic!("unknown role {other}"),
                },
                pieces: recorded_pieces(&message["pieces"]).leak(),
            })
            .collect();
        let got = model.build_delay_prompt(&messages, &template, mode);
        assert_eq!(
            got.expect("prompt rows"),
            i32_rows(&case["rows"]),
            "case {}",
            case["name"]
        );
    }
}

#[test]
fn continuation_user_audio_keeps_its_trailing_text() {
    // The reference forces truncation off for user messages, so the text
    // after a user's reference audio survives continuation mode. Only the
    // assistant block is truncated.
    const TRAILING: i32 = 4242;
    let model = delay_model("delay_generate");
    let n_vq = delay_config().n_vq;
    let template = super::ChatTemplateIds {
        user_role: &[],
        assistant_role: &[],
        after_im_end: &[],
    };
    let user_codes = vec![vec![1; n_vq]; 3];
    let assistant_codes = vec![vec![2; n_vq]; 3];
    let user_pieces = [
        super::ContentPiece::Text(&[10]),
        super::ContentPiece::Audio(&user_codes),
        super::ContentPiece::Text(&[TRAILING]),
    ];
    let assistant_pieces = [
        super::ContentPiece::Text(&[20]),
        super::ContentPiece::Audio(&assistant_codes),
    ];
    let messages = [
        DelayMessage {
            role: Role::User,
            pieces: &user_pieces,
        },
        DelayMessage {
            role: Role::Assistant,
            pieces: &assistant_pieces,
        },
    ];
    let rows = model
        .build_delay_prompt(&messages, &template, DelayMode::Continuation)
        .expect("continuation prompt rows");
    assert!(
        rows.iter().any(|row| row[0] == TRAILING),
        "user trailing text was dropped by continuation truncation"
    );
}

#[test]
fn delay_pattern_round_trip_matches_the_reference() {
    let traces = read_json(&testdata("delay_pattern/traces.json"));
    let codes = i32_rows(&traces["codes"]);
    let n_vq = traces["n_vq"].as_u64().expect("n_vq") as usize;
    let pad = traces["pad_code"].as_i64().expect("pad") as i32;
    let delayed = apply_delay_pattern(&codes, pad, n_vq).unwrap();
    assert_eq!(delayed, i32_rows(&traces["delayed"]));
    let restored = apply_de_delay_pattern(&delayed, n_vq).unwrap();
    assert_eq!(restored, i32_rows(&traces["restored"]));
    // Degenerate grids stay empty instead of underflowing.
    assert!(apply_de_delay_pattern(&delayed[..n_vq - 1], n_vq)
        .unwrap()
        .is_empty());
}

#[test]
fn delay_generation_matches_the_reference_tails() {
    for (case_name, expected_stop) in [("delay_generate", false), ("delay_stop", true)] {
        let traces = read_json(&testdata(&format!("{case_name}/traces.json")));
        let prompt_rows = i32_rows(&traces["prompt_rows"]);
        let mut model = delay_model(case_name);
        let params = DelayParams {
            max_new_tokens: traces["max_new_tokens"].as_u64().expect("steps") as usize,
            text_temperature: 0.0,
            audio_temperature: 0.0,
            text_top_p: 0.8,
            audio_top_p: 0.8,
            text_top_k: 50,
            audio_top_k: 25,
            audio_repetition_penalty: 1.2,
        };
        let (start_length, rows) = model
            .generate_delay_pattern_ids(&prompt_rows, &params, 0)
            .expect("generate runs");
        assert_eq!(
            start_length,
            traces["start_length"].as_u64().unwrap() as usize
        );
        assert_eq!(rows, i32_rows(&traces["rows"]), "{case_name} rows");
        assert_eq!(
            rows.iter().map(|row| row[0]).collect::<Vec<_>>(),
            i32_vec(&traces["text_tokens"]),
            "{case_name} text tokens"
        );
        let stopped = rows
            .last()
            .map(|row| row[0] == model.config.im_end_token_id)
            .unwrap_or(false);
        assert_eq!(stopped, expected_stop, "{case_name} stop state");

        // The decode: the reference trim may consume the whole first
        // segment (start_length exceeds the code count for the character
        // tokenizer), so the untrimmed waveform pins the codec parity.
        let tokenizer = audio_tokenizer();
        let (wave, token_count) = model
            .decode_generated_audio(&tokenizer, start_length, &rows)
            .expect("decode runs");
        assert_eq!(
            token_count,
            traces["token_count"].as_u64().unwrap() as usize
        );
        let want_wave = f32_vec(&traces["waveform"]);
        assert_eq!(wave.len(), want_wave.len(), "{case_name} trimmed length");
        if !wave.is_empty() {
            let diff = max_abs_diff(&wave, &want_wave);
            assert!(diff <= WAVEFORM_TOLERANCE, "{case_name} wave diff {diff}");
        }
        let want_untrimmed = f32_vec(&traces["waveform_untrimmed"]);
        assert!(!want_untrimmed.is_empty(), "{case_name} untrimmed fixture");
        let untrimmed = untrimmed_decode(
            model.config.n_vq,
            model.config.audio_pad_code,
            &rows,
            &tokenizer,
        );
        let diff = max_abs_diff(&untrimmed, &want_untrimmed);
        assert!(
            diff <= WAVEFORM_TOLERANCE,
            "{case_name} untrimmed diff {diff}"
        );
    }
}

/// The trim-free decode: de-delay, drop all-pad rows, contiguous
/// segments through the codec (the reference `_decode_generated_audio`
/// segment logic without the first-segment trim).
fn untrimmed_decode(
    n_vq: usize,
    pad_code: i32,
    rows: &[Vec<i32>],
    tokenizer: &MossAudioTokenizer,
) -> Vec<f32> {
    let audio_codes: Vec<Vec<i32>> = rows.iter().map(|row| row[1..].to_vec()).collect();
    let codes = apply_de_delay_pattern(&audio_codes, n_vq).expect("de-delay");
    let non_pad: Vec<usize> = codes
        .iter()
        .enumerate()
        .filter(|(_, row)| row.iter().any(|&code| code != pad_code))
        .map(|(index, _)| index)
        .collect();
    if non_pad.is_empty() {
        return Vec::new();
    }
    let mut breaks = vec![0usize];
    for index in 1..non_pad.len() {
        if non_pad[index] != non_pad[index - 1] + 1 {
            breaks.push(index);
        }
    }
    breaks.push(non_pad.len());
    let mut samples = Vec::new();
    for window in breaks.windows(2) {
        let indices = &non_pad[window[0]..window[1]];
        let segment = &codes[indices[0]..indices[indices.len() - 1] + 1];
        let books: Vec<Vec<i32>> = (0..n_vq)
            .map(|book| segment.iter().map(|row| row[book]).collect())
            .collect();
        samples.extend(tokenizer.decode(&books).expect("codec decode"));
    }
    samples
}

#[test]
fn v15_prompt_rows_match_the_reference_layouts() {
    let traces = read_json(&testdata("v15_prompt/traces.json"));
    let model = delay_model("v15_generate");
    let pieces = &traces["template"];
    let template = V15TemplateIds {
        user_role_prefix: i32_vec(&pieces["user_role_prefix"]).leak(),
        user_template_reference_prefix: i32_vec(&pieces["user_template_reference_prefix"]).leak(),
        user_template_after_reference: i32_vec(&pieces["user_template_after_reference"]).leak(),
        user_template_suffix: i32_vec(&pieces["user_template_suffix"]).leak(),
        assistant_turn_prefix: i32_vec(&pieces["assistant_turn_prefix"]).leak(),
        assistant_role_prefix: i32_vec(&pieces["assistant_role_prefix"]).leak(),
        none_reference: i32_vec(&pieces["none_reference"]).leak(),
    };
    let text_ids = i32_vec(&traces["text_ids"]);
    let ref_text_ids = i32_vec(&traces["ref_text_ids"]);
    let codes = reference_codes();
    for case in traces["cases"].as_array().expect("cases") {
        let got = match case["name"].as_str().expect("name") {
            "voice_clone" => model.build_v15_inference_input_ids(
                V15PromptMode::Generation,
                &template,
                &text_ids,
                Some(std::slice::from_ref(&codes)),
            ),
            "generation_text_only" => model.build_v15_inference_input_ids(
                V15PromptMode::Generation,
                &template,
                &text_ids,
                None,
            ),
            "continuation" => {
                // The reference concatenates ref text + text as one
                // string; the character tokenizer keeps the id split.
                let mut combined = ref_text_ids.clone();
                combined.extend_from_slice(&text_ids);
                model.build_v15_inference_input_ids(
                    V15PromptMode::Continuation,
                    &template,
                    &combined,
                    Some(std::slice::from_ref(&codes)),
                )
            }
            other => panic!("unknown prompt case {other}"),
        };
        assert_eq!(
            got.expect("prompt rows"),
            i32_rows(&case["rows"]),
            "case {}",
            case["name"]
        );
    }
}

#[test]
fn v15_generation_matches_the_reference_frames_and_waveform() {
    let traces = read_json(&testdata("v15_generate/traces.json"));
    let prompt_rows = i32_rows(&traces["prompt_rows"]);
    let mut model = delay_model("v15_generate");
    let params = V15Params {
        max_new_tokens: traces["max_new_frames"].as_u64().expect("frames") as usize,
        do_sample: false,
        text_temperature: 1.0,
        audio_temperature: 1.0,
        text_top_p: 0.8,
        audio_top_p: 0.8,
        text_top_k: 50,
        audio_top_k: 25,
        audio_repetition_penalty: 1.2,
        use_kv_cache: true,
    };
    let (start_length, rows) = model
        .generate_v15_local_ids(&prompt_rows, &params, 0)
        .expect("generate runs");
    assert_eq!(
        start_length,
        traces["start_length"].as_u64().unwrap() as usize
    );
    assert_eq!(rows, i32_rows(&traces["rows"]), "v15 rows");

    let tokenizer = audio_tokenizer();
    let (wave, token_count) = model
        .decode_generated_audio(&tokenizer, start_length, &rows)
        .expect("decode runs");
    assert_eq!(
        token_count,
        traces["token_count"].as_u64().unwrap() as usize
    );
    let want_wave = f32_vec(&traces["waveform"]);
    assert_eq!(wave.len(), want_wave.len());
    let diff = max_abs_diff(&wave, &want_wave);
    assert!(diff <= WAVEFORM_TOLERANCE, "v15 wave diff {diff}");

    // The generate entry returns the same result for the v1.5 variant.
    let generated = model
        .generate(
            &tokenizer,
            &prompt_rows,
            &GenerationParams::V15Local(params.clone()),
            0,
        )
        .expect("generate entry runs");
    assert_eq!(generated.rows, rows);
    assert_eq!(generated.samples, wave);
}

#[test]
fn v15_engineered_stop_ends_with_no_frames() {
    let traces = read_json(&testdata("v15_stop/traces.json"));
    let prompt_rows = i32_rows(&traces["prompt_rows"]);
    let mut model = delay_model("v15_stop");
    let params = V15Params {
        max_new_tokens: traces["max_new_frames"].as_u64().expect("frames") as usize,
        do_sample: false,
        ..V15Params::default()
    };
    let tokenizer = audio_tokenizer();
    let generated = model
        .generate(
            &tokenizer,
            &prompt_rows,
            &GenerationParams::V15Local(params),
            0,
        )
        .expect("generate runs");
    assert_eq!(generated.rows, i32_rows(&traces["rows"]));
    assert_eq!(generated.token_count, 0);
    assert!(generated.samples.is_empty());
}

#[test]
fn family_sampler_matches_the_reference_on_fixed_logits() {
    let traces = read_json(&testdata("sampling/traces.json"));
    for case in traces["cases"].as_array().expect("cases") {
        let logits = f32_vec(&case["logits"]);
        if let Some(penalized) = case["penalized"].as_array() {
            let mut scores = logits.clone();
            family_sampling::apply_repetition_penalty(
                &mut scores,
                &i32_vec(&case["context"]),
                case["repetition_penalty"].as_f64().expect("penalty") as f32,
            );
            let diff = max_abs_diff(&scores, &f32_vec(&Value::Array(penalized.clone())));
            assert!(diff <= 2e-6, "case {} penalty diff {diff}", case["name"]);
        }
        if let Some(top_k) = case["top_k_scores"].as_array() {
            let scaled: Vec<f32> = logits
                .iter()
                .map(|&x| x / case["temperature"].as_f64().unwrap() as f32)
                .collect();
            let filtered = family_sampling::apply_top_k(
                &scaled,
                Some(case["top_k"].as_u64().expect("top_k") as usize),
            )
            .unwrap();
            let diff = max_abs_diff(&filtered, &f32_vec_masked(&Value::Array(top_k.clone())));
            assert!(diff <= 2e-6, "case {} top_k diff {diff}", case["name"]);
        }
        if let Some(top_p) = case["top_p_scores"].as_array() {
            let scaled: Vec<f32> = logits
                .iter()
                .map(|&x| x / case["temperature"].as_f64().unwrap() as f32)
                .collect();
            // The chained case applies top-p on top of the recorded
            // top-k output; a standalone case applies it on the scores.
            let base = if case["top_k_scores"].is_null() {
                scaled
            } else {
                family_sampling::apply_top_k(
                    &scaled,
                    Some(case["top_k"].as_u64().expect("top_k") as usize),
                )
                .unwrap()
            };
            let filtered = family_sampling::apply_top_p(
                &base,
                Some(case["top_p"].as_f64().expect("top_p") as f32),
            )
            .unwrap();
            let diff = max_abs_diff(&filtered, &f32_vec_masked(&Value::Array(top_p.clone())));
            assert!(diff <= 2e-6, "case {} top_p diff {diff}", case["name"]);
        }
        if let Some(token) = case["greedy_token"].as_u64() {
            let got = family_sampling::sample_token(
                &logits,
                Some(&i32_vec(&case["context"])),
                case["repetition_penalty"].as_f64().expect("penalty") as f32,
                Some(0.8),
                Some(25),
                false,
                crate::music::minimax_music3::rng::Key::new(1),
            )
            .unwrap();
            assert_eq!(got, token as usize, "case {} greedy", case["name"]);
        }
    }
}

#[test]
fn v15_local_refuses_a_gpt2_width_that_differs_from_the_backbone() {
    // The local stack takes global hidden states with no projection, so a
    // gpt2 width other than the backbone hidden size must be refused at
    // load, before any local tensor is read.
    let dir = testdata("v15_generate");
    let mut config = v15_config();
    let hidden = config.language_config.hidden_size();
    config.gpt2_config.as_mut().expect("v15 gpt2_config").n_embd = hidden + 8;
    let transformer = super::open_backbone_weights(&dir, "transformer").expect("transformer");
    let weights = crate::lm::Weights::open(&dir).expect("weights");
    let err = Model::load_v15_local(&transformer, &weights, config)
        .err()
        .expect("width mismatch refused");
    match err {
        crate::SpeechError::BadConfig { field, .. } => {
            assert_eq!(field, "gpt2_config.n_embd");
        }
        other => panic!("expected BadConfig, got {other:?}"),
    }
}

#[test]
fn backbone_refuses_zero_kv_heads_at_load() {
    // The GQA group size is `heads / kv_heads`; zero kv heads used to panic
    // on the first forward. The shared engine now refuses it at load.
    let dir = testdata("v15_generate");
    let weights = crate::lm::Weights::open(&dir).expect("weights");
    let mut dense = v15_config().language_config.dense.clone();
    dense.num_key_value_heads = 0;
    let err = crate::lm::engine::Backbone::load(&weights, dense)
        .err()
        .expect("zero kv heads refused");
    match err {
        crate::SpeechError::BadConfig { field, .. } => {
            assert_eq!(field, "num_key_value_heads");
        }
        other => panic!("expected BadConfig, got {other:?}"),
    }
}

#[test]
fn logit_masks_refuse_out_of_vocab_ids() {
    // A config id past the logits row used to be dropped silently, which
    // removed the constraint. Now it is an error at both mask helpers.
    let mut logits = vec![0.0f32; 4];
    assert!(super::set_logits_to_neg_inf(&mut logits, &[7]).is_err());
    assert!(super::keep_only_logits(&mut logits, &[-1]).is_err());
    super::set_logits_to_neg_inf(&mut logits, &[3]).expect("in range");
    assert_eq!(logits[3], f32::NEG_INFINITY);
    assert_eq!(logits[0], 0.0);
}

#[test]
fn unified_codes_refuse_interleaved_audio_placeholders() {
    // Start ids that precede the previous block's end used to underflow the
    // pad-gap subtraction. Two starts before two ends must be an input error.
    let config = delay_config();
    let model = delay_model("delay_generate");
    let n_vq = config.n_vq;
    let start = config.audio_start_token_id;
    let end = config.audio_end_token_id;
    let content = [start, start, end, end];
    let codes = vec![vec![1; n_vq]];
    let blocks: [&[Vec<i32>]; 2] = [&codes, &codes];
    let err = model
        .build_delay_unified_codes(&content, &blocks, false)
        .err()
        .expect("interleaved placeholders refused");
    assert!(
        matches!(err, crate::SpeechError::Input { .. }),
        "expected Input, got {err:?}"
    );
}

#[test]
fn config_refuses_zero_channels_and_zero_heads() {
    // n_vq = 0 leaves no audio tables; the moss gpt2 config reuses the nano
    // parser, so a zero head count must be refused there too (it used to
    // panic on `n_embd % n_head`).
    assert!(ModelConfig::from_json(&serde_json::json!({"n_vq": 0})).is_err());
    assert!(ModelConfig::from_json(&serde_json::json!({
        "model_type": "moss_tts_local",
        "gpt2_config": {"n_head": 0},
    }))
    .is_err());
}

#[test]
fn normalize_audio_codes_transposes_and_truncates() {
    // Codebook-major input ([4 books, 3 frames]) transposes.
    let codebook_major = vec![
        vec![1, 2, 3],
        vec![4, 5, 6],
        vec![7, 8, 9],
        vec![10, 11, 12],
    ];
    let got = normalize_audio_codes(&codebook_major, 4).expect("transposes");
    assert_eq!(
        got,
        vec![vec![1, 4, 7, 10], vec![2, 5, 8, 11], vec![3, 6, 9, 12]]
    );
    // Rows truncate to n_vq.
    let wide = vec![vec![1, 2, 3, 4, 5, 6], vec![7, 8, 9, 10, 11, 12]];
    let got = normalize_audio_codes(&wide, 4).expect("truncates");
    assert_eq!(got, vec![vec![1, 2, 3, 4], vec![7, 8, 9, 10]]);
    // Fewer channels than n_vq without enough rows to transpose refuses.
    let short = vec![vec![1, 2, 3]];
    assert!(normalize_audio_codes(&short, 4).is_err());
}
